        "encodings": [
          "length=value or share",
          "color=part",
          "facet=whole"
        ],
        "invariants": [
          "Totals and denominators are visible.",
          "Parts keep stable identity across wholes.",
          "Tiny parts remain discoverable without false area precision."
        ]
